import fs from 'node:fs';
import path from 'node:path';
import { createHash } from 'node:crypto';
import lighthouse from './node_modules/lighthouse/core/index.js';
import { launch } from './node_modules/chrome-launcher/dist/index.js';
import chromium, { inflate, setupLambdaEnvironment } from './node_modules/@sparticuz/chromium/build/index.js';
import { throttling, screenEmulationMetrics, userAgents } from './node_modules/lighthouse/core/config/constants.js';

await inflate(path.resolve('node_modules/@sparticuz/chromium/bin/al2023.tar.br'));
setupLambdaEnvironment('/tmp/al2023/lib');
const cases = [
  { name: 'mobile-home', mode: 'mobile', route: '/' },
  { name: 'mobile-catalog', mode: 'mobile', route: '/products' },
  { name: 'mobile-product', mode: 'mobile', route: '/products/br-mods-pc' },
  { name: 'mobile-payments', mode: 'mobile', route: '/payments' },
  { name: 'desktop-home', mode: 'desktop', route: '/' },
];
const dir = '/home/user/abn-final-lighthouse';
fs.mkdirSync(dir, { recursive: true });
const selected = cases.filter(c => process.argv.slice(2).includes(c.name));
if (!selected.length) throw new Error('Pass one or more case names.');
for (const item of selected) {
  const target = `http://127.0.0.1:3000${item.route}`;
  const warm = await fetch(target);
  if (warm.status !== 200) throw new Error(`Warm request failed: ${item.route}: ${warm.status}`);
  await warm.text();
  const settings = {
    onlyCategories: ['performance'],
    formFactor: item.mode,
    screenEmulation: item.mode === 'mobile' ? screenEmulationMetrics.mobile : { ...screenEmulationMetrics.desktop, width: 1440, height: 900 },
    emulatedUserAgent: userAgents[item.mode],
    throttlingMethod: 'simulate',
    throttling: item.mode === 'mobile' ? throttling.mobileSlow4G : { ...throttling.desktopDense4G, rttMs: 40, throughputKbps: 10240, cpuSlowdownMultiplier: 1 },
  };
  for (let run = 1; run <= 3; run++) {
    const output = `${dir}/${item.name}-${run}.json`;
    const brief = `${dir}/${item.name}-${run}-metrics.json`;
    if (fs.existsSync(brief)) { console.log(`Already recorded ${item.name} ${run}`); continue; }
    const chrome = await launch({
      chromePath: await chromium.executablePath(),
      chromeFlags: chromium.args.filter(arg => !['--disable-web-security', '--allow-running-insecure-content', '--single-process'].includes(arg)),
      logLevel: 'silent',
    });
    try {
      const result = await lighthouse(target, { port: chrome.port, logLevel: 'error', output: 'json' }, { extends: 'lighthouse:default', settings });
      if (!result || result.lhr.runtimeError) throw new Error(JSON.stringify(result?.lhr.runtimeError ?? 'No result'));
      const lhr = result.lhr;
      fs.writeFileSync(output, JSON.stringify(lhr));
      const metrics = {
        ...item, run, fetchedAt: lhr.fetchTime, lighthouseVersion: lhr.lighthouseVersion,
        environment: lhr.environment, settings: lhr.configSettings,
        performanceScore: Math.round(lhr.categories.performance.score * 100),
        lcpMs: lhr.audits['largest-contentful-paint'].numericValue,
        tbtMs: lhr.audits['total-blocking-time'].numericValue,
        cls: lhr.audits['cumulative-layout-shift'].numericValue,
        fcpMs: lhr.audits['first-contentful-paint'].numericValue,
        speedIndexMs: lhr.audits['speed-index'].numericValue,
        warnings: lhr.runWarnings,
        reportSha256: createHash('sha256').update(fs.readFileSync(output)).digest('hex'),
      };
      fs.writeFileSync(brief, JSON.stringify(metrics, null, 2));
      console.log(`${item.name} ${run}/3: score=${metrics.performanceScore}, LCP=${(metrics.lcpMs / 1000).toFixed(3)}s, TBT=${(metrics.tbtMs / 1000).toFixed(3)}s, CLS=${metrics.cls}`);
    } finally { await chrome.kill(); }
  }
}
